select energy_manager.load_cards($cards$[
{"id":"p2-b01-040","paper":2,"topic":"Fuels & Combustion","kind":"problem","front":"Measured CO₂ in an oil-fired boiler flue gas is 8% and the theoretical CO₂ for the fuel is 16%. Estimate the % excess air.","back":"About 94%.","explain":"This is the short-type question S-3 in the chapter, worked with the oil-firing excess air relation. The constant 7900 comes from that relation.","flash":false,"source":"BEE Book 2 Ch 01 p48","steps":[{"prompt":"Calculate the numerator.","answer":"7900 × (16 − 8) = 63,200.","explain":"Uses theoretical minus actual CO₂."},{"prompt":"Calculate the denominator.","answer":"8 × (100 − 16) = 672.","explain":"Uses actual CO₂ times the non-CO₂ share at theoretical."},{"prompt":"Find the excess air.","answer":"63,200 / 672 = 94.0%.","explain":"Lower measured CO₂ than theoretical means more excess air."}],"order":2129},
{"id":"p2-b02-001","paper":2,"topic":"Boiler Basics","kind":"fact","front":"By roughly how much does water's volume increase when it is boiled into steam, and why does this make boilers dangerous?","back":"About 1,600 times. The expansion force is almost as explosive as gunpowder, so boilers must be handled with the utmost care.","explain":"Water is a cheap, useful heat carrier, but its huge volume increase on boiling is what makes a boiler a serious pressure hazard. This is why boilers are subject to statutory control under the Indian Boiler Regulation.","flash":true,"source":"BEE Book 2 Ch 02 p53","order":2130},
{"id":"p2-b02-002","paper":2,"topic":"Heat Transfer","kind":"fact","front":"Name the three modes of heat transfer and what each one needs.","back":"Radiation: heat from a hot body to a cold body with no conveying medium. Convection: heat carried by a medium such as air or water. Conduction: heat passed by direct contact, molecule to molecule.","explain":"In boilers, radiation and convection dominate heat transfer from the combustion gases, while conduction carries heat through the metal walls. Identify each mode by what, if anything, carries the heat.","flash":false,"source":"BEE Book 2 Ch 02 p53","order":2131},
{"id":"p2-b02-003","paper":2,"topic":"Boiler Rating","kind":"fact","front":"What is the Maximum Continuous Rating (MCR) of a boiler?","back":"The hourly evaporation (steam output) the boiler can maintain for 24 hours continuously, usually quoted in tonnes per hour (TPH). A specification may read MCR 10 TPH (F & A 100 °C).","explain":"F & A means from and at 100 °C: the steam generated from water at 100 °C to saturated steam at 100 °C. So a 10 TPH rating means 10 tonnes of steam evaporated per hour.","flash":false,"source":"BEE Book 2 Ch 02 p53","order":2132},
{"id":"p2-b02-004","paper":2,"topic":"Indian Boiler Regulation","kind":"fact","front":"Under which Act and sections was the Indian Boiler Regulation (IBR) created, and in which year was it amended?","back":"Created under sections 28 and 29 of the Indian Boilers Act. Amended by the Indian Boilers (Amendment) Act, 2007.","explain":"The IBR defines a boiler as a pressure vessel in which steam is generated for use external to itself by the application of heat, wholly or partly under pressure when steam is shut off.","flash":false,"source":"BEE Book 2 Ch 02 p53","order":2133},
{"id":"p2-b02-005","paper":2,"topic":"IBR Definitions","kind":"fact","front":"Under the IBR, when is a pipe classed as a steam pipe?","back":"When steam pressure exceeds 3.5 kg/cm² above atmospheric, or when the internal diameter exceeds 254 mm and steam pressure exceeds 1 kg/cm² above atmospheric.","explain":"Any connected fitting of a steam pipe is included in the definition. The second test covers large-diameter lines operating at lower pressure.","flash":false,"source":"BEE Book 2 Ch 02 p54","order":2134},
{"id":"p2-b02-006","paper":2,"topic":"Feed Water","kind":"fact","front":"What are the two sources of boiler feed water?","back":"(1) Condensate returned from the processes, and (2) makeup water, which is treated raw water brought in from outside the boiler room and plant processes.","explain":"Returned condensate carries heat that would otherwise be lost, so it is valuable. Makeup water replaces the losses and must be treated before use.","flash":false,"source":"BEE Book 2 Ch 02 p55","order":2135},
{"id":"p2-b02-007","paper":2,"topic":"Boiler Types","kind":"fact","front":"How do fire tube and water tube boilers differ in where the water and the hot gases are?","back":"Fire tube: hot gases pass through the tubes with water around them. Water tube: water passes through the tubes with hot gases outside them.","explain":"Fire tube boilers usually cost less upfront and are more fuel efficient, but are generally limited to about 25 t/hr and 17.5 kg/cm². Water tube boilers can be built for any capacity or pressure and have higher efficiency.","flash":false,"source":"BEE Book 2 Ch 02 p55","order":2136},
{"id":"p2-b02-008","paper":2,"topic":"Stoker Boilers","kind":"fact","front":"Why is the spreader stoker often preferred in industrial boilers?","back":"It burns fine coal in suspension and larger particles on a thin, fast-burning grate bed. It handles load swings well because ignition is almost instant when the firing rate is raised.","explain":"Spreader stokers combine suspension burning and grate burning. Their load flexibility is why they are favoured over other stoker types in many industrial applications.","flash":false,"source":"BEE Book 2 Ch 02 p57","order":2137},
{"id":"p2-b02-009","paper":2,"topic":"Pulverised Coal","kind":"fact","front":"What fineness should pulverised bituminous coal have, and why must it be neither too fine nor too coarse?","back":"Less than 2% above 300 µm and 70–75% below 75 µm. Too fine wastes grinding mill power; too coarse does not burn completely and raises unburnt losses.","explain":"Particles must burn out within the residence time of about 2 to 5 seconds at 1300–1700 °C. Fineness links grinding power directly to combustion losses.","flash":false,"source":"BEE Book 2 Ch 02 p57","order":2138},
{"id":"p2-b02-010","paper":2,"topic":"Supercritical Boilers","kind":"fact","front":"How do sub-critical and supercritical boilers differ in their heat-transfer sections?","back":"Sub-critical boilers have three distinct sections: economiser, evaporator and superheater. Supercritical boilers have only an economiser and a superheater.","explain":"Above the critical point (221.2 bar absolute, 374.18 °C) water becomes steam without a separate boiling stage. With no two-phase mixture, erosion and corrosion problems are reduced.","flash":false,"source":"BEE Book 2 Ch 02 p58","order":2139},
{"id":"p2-b02-011","paper":2,"topic":"Evaporation Ratio","kind":"fact","front":"What are the typical evaporation ratios for biomass, coal, gas and oil fired boilers?","back":"Biomass 2.0–3.0; coal 4.0–5.5; gas 11.0–13.0; oil 13.5–14.5 (kg of steam per kg of fuel).","explain":"Oil and gas firing gives far higher ratios than solid fuels. Compare a boiler only with its own past values: a drop in its ratio means a drop in efficiency.","flash":true,"source":"BEE Book 2 Ch 02 p59","order":2140},
{"id":"p2-b02-012","paper":2,"topic":"Boiler Efficiency","kind":"fact","front":"What is the difference between the direct and indirect methods of finding boiler efficiency?","back":"Direct (input-output) method: useful steam energy divided by the fuel energy input. Indirect (loss) method: 100% minus the sum of all percentage heat losses.","explain":"The direct method needs only steam output, fuel input and a few temperatures, so it is quick. The indirect method shows where each loss occurs, so it points to improvement opportunities.","flash":false,"source":"BEE Book 2 Ch 02 p59","order":2141},
{"id":"p2-b02-013","paper":2,"topic":"Boiler Efficiency","kind":"fact","front":"Does the standard indirect (heat loss) efficiency calculation include blowdown loss?","back":"No. The standards do not include blow down loss in the efficiency determination.","explain":"Blowdown is a real energy and water cost, but it is handled separately and is not one of the L1 to L8 losses in the indirect method.","flash":true,"source":"BEE Book 2 Ch 02 p61","order":2142},
{"id":"p2-b02-014","paper":2,"topic":"Water Treatment","kind":"fact","front":"Which hardness salts are temporary and which are permanent, and why?","back":"Calcium and magnesium bicarbonates (alkaline hardness) are temporary: heating breaks them down into a soft sludge that settles out. Calcium and magnesium sulphates, chlorides and nitrates are permanent: they form hard scale that is difficult to remove.","explain":"Temporary hardness can be removed by boiling. Permanent hardness comes out of solution as hard scale as temperature and concentration rise inside the boiler.","flash":false,"source":"BEE Book 2 Ch 02 p66","order":2143},
{"id":"p2-b02-015","paper":2,"topic":"Water Treatment","kind":"fact","front":"Why is silica a problem in boiler water?","back":"It forms hard silicate scales and calcium or magnesium silicates of very low thermal conductivity. It can also be carried over to steam turbines and deposit on the blades.","explain":"Silica carry-over happens either in water droplets in the steam or as volatile silica at higher pressures.","flash":false,"source":"BEE Book 2 Ch 02 p66","order":2144},
{"id":"p2-b02-016","paper":2,"topic":"Water Treatment","kind":"fact","front":"Is internal treatment alone recommended for boiler water?","back":"No. Internal treatment alone is not recommended. It suits only boilers with low-hardness feed water, low pressure, a tolerance for high TDS and small water volumes.","explain":"Internal treatment turns scale-forming compounds into free-flowing sludge that is removed by blowdown. Where feed water is hard, high blowdown rates would be needed, which is uneconomical in heat and water.","flash":false,"source":"BEE Book 2 Ch 02 p66","order":2145},
{"id":"p2-b02-017","paper":2,"topic":"Ion Exchange","kind":"fact","front":"In base-exchange softening, what does the resin exchange, and does it reduce TDS or blowdown?","back":"Calcium and magnesium ions are exchanged for sodium ions, and the resin is regenerated with sodium chloride. It does NOT reduce TDS, alkalinity or the blowdown quantity.","explain":"Sodium salts are soluble and do not form scale. Demineralisation, which removes all salts, is needed to cut TDS and blowdown.","flash":false,"source":"BEE Book 2 Ch 02 p67","order":2146},
{"id":"p2-b02-018","paper":2,"topic":"Deaeration","kind":"fact","front":"What dissolved oxygen levels can vacuum and pressure-type deaerators reach?","back":"Vacuum type (operates near 82 °C): below 0.02 mg/litre O₂. Pressure type (minimum about 105 °C): about 0.005 mg/litre O₂.","explain":"Vacuum types need a vacuum pump or steam ejector. Pressure types hold the operating pressure with a control valve that admits steam into the feed water.","flash":true,"source":"BEE Book 2 Ch 02 p68","order":2147},
{"id":"p2-b02-019","paper":2,"topic":"Chemical De-aeration","kind":"fact","front":"How do sodium sulphite and hydrazine differ as oxygen scavengers?","back":"Sodium sulphite forms sodium sulphate, which raises boiler water TDS and so raises blowdown. Hydrazine forms nitrogen and water, adds no TDS, and is used in high-pressure boilers.","explain":"A chemical scavenger removes the trace oxygen left after mechanical deaeration. Hydrazine is chosen when low boiler water solids are needed.","flash":false,"source":"BEE Book 2 Ch 02 p68","order":2148},
{"id":"p2-b02-020","paper":2,"topic":"Boiler Blowdown","kind":"fact","front":"Why is conductivity measured to control boiler water TDS?","back":"Measuring TDS directly is tedious and slow, so conductivity is used to monitor overall TDS. A rise in conductivity means the boiler water is becoming more contaminated.","explain":"Conductivity responds to dissolved solids and can be read quickly. Automatic blowdown controls sense conductivity and pH and respond to them.","flash":false,"source":"BEE Book 2 Ch 02 p71","order":2149},
{"id":"p2-b02-021","paper":2,"topic":"Boiler Blowdown","kind":"fact","front":"What maximum boiler water TDS does the book give for package and economic boilers?","back":"3,000 ppm. For comparison: Lancashire boilers 10,000 ppm; smoke and water tube boilers at 12 kg/cm² 5,000 ppm.","explain":"These are recommended maxima from the book's Table 2.4. The table itself says to follow the manufacturer's guidelines for a specific boiler.","flash":false,"source":"BEE Book 2 Ch 02 p71","order":2150},
{"id":"p2-b02-022","paper":2,"topic":"Blowdown Types","kind":"fact","front":"What is intermittent blowdown, and what thumb rule is given for it?","back":"Manually opening a large-diameter valve at the lowest point of the shell for a short time, e.g. once in a shift for 2 minutes.","explain":"It causes TDS and water-level swings and loses a lot of heat. Continuous blowdown avoids these swings, but wastes heat unless it is recovered.","flash":false,"source":"BEE Book 2 Ch 02 p71","order":2151},
{"id":"p2-b02-023","paper":2,"topic":"Blowdown Types","kind":"fact","front":"How is heat recovered from continuous blowdown?","back":"Blow the hot, concentrated water into a flash tank to generate flash steam, which can preheat feed water or be used for other purposes.","explain":"Continuous blowdown keeps TDS and steam purity steady with no regular operator intervention. It is common in high-pressure boilers.","flash":false,"source":"BEE Book 2 Ch 02 p72","order":2152},
{"id":"p2-b02-024","paper":2,"topic":"Soot Blowing","kind":"fact","front":"How much fuel can 3 mm of soot cost, and what flue gas temperature rise signals soot build-up?","back":"3 mm of soot can raise fuel consumption by about 2.5%. A flue gas temperature rise of about 20 °C above the normal value for a newly cleaned boiler signals soot deposits.","explain":"Soot insulates heat-transfer surfaces. Stack temperature checked and recorded regularly is the simplest indicator of when to blow soot.","flash":false,"source":"BEE Book 2 Ch 02 p74","order":2153},
{"id":"p2-b02-025","paper":2,"topic":"Boiler Preservation","kind":"fact","front":"When is wet preservation used instead of dry preservation for a boiler?","back":"Wet method: boilers kept ready for standby or sudden demand. Dry method: boilers scheduled to be out of service for a long time and not expected to restart at short notice.","explain":"Wet preservation keeps treated water in the boiler, so the chemical levels must be monitored. Dry preservation removes the water and uses desiccants inside the drum.","flash":false,"source":"BEE Book 2 Ch 02 p74","order":2154},
{"id":"p2-b02-026","paper":2,"topic":"Start-up Procedure","kind":"fact","front":"How long should a cold boiler start-up take, and until when are the vents kept open?","back":"About four hours; firing must not be speeded up. Keep the vents open until a heavy steam jet flows, which is about 1 bar of boiler pressure.","explain":"Quick, uneven temperature rises overstrain the boiler material. The furnace must be pre-purged for a set time before firing to avoid a starting explosion.","flash":false,"source":"BEE Book 2 Ch 02 p75","order":2155},
{"id":"p2-b02-027","paper":2,"topic":"Shutdown Procedure","kind":"fact","front":"What should be done to blowdown and chemicals three to five days before a planned boiler shutdown?","back":"Increase blowdown by 50%; raise alkalinity to at least 500 ppm if possible without foaming or carryover; increase the sludge conditioner by 50 to 100%. Scale inhibitor and oxygen scavenger feed must rise to keep normal residuals.","explain":"The aim is to stop sludge settling and baking onto tube surfaces, where it may later need mechanical or chemical cleaning.","flash":false,"source":"BEE Book 2 Ch 02 p76","order":2156},
{"id":"p2-b02-028","paper":2,"topic":"Thermic Fluid Heaters","kind":"fact","front":"At what temperature can a thermic fluid heater work at atmospheric pressure, and what steam pressure would be needed for the same temperature?","back":"Up to 300 °C at atmospheric pressure. Steam would need about 85 bar to reach 300 °C.","explain":"Thermic fluid also avoids feed water treatment, condensate flash losses and corrosion risk, and it gives optional temperature set points.","flash":true,"source":"BEE Book 2 Ch 02 p76","order":2157},
{"id":"p2-b02-029","paper":2,"topic":"Economiser","kind":"fact","front":"What gain did the book give for an economiser on an older shell boiler with 260 °C flue gas?","back":"Flue gas cut from 260 °C to 200 °C, feed water up about 15 °C, and overall thermal efficiency up by roughly 3%.","explain":"A condensing economiser on a modern 3-pass natural gas boiler (flue gas 140 °C to 65 °C) gives about 5%. Flue exit is usually kept at 200 °C minimum for fuels with sulphur, to prevent SOx corrosion.","flash":false,"source":"BEE Book 2 Ch 02 p78","order":2158},
{"id":"p2-b02-030","paper":2,"topic":"Combustion Air Preheat","kind":"fact","front":"How much must combustion air temperature rise to gain 1% in thermal efficiency?","back":"About 20 °C.","explain":"Air preheat is an alternative to feed water heating, using a heat exchanger in the exit flue. Modern burners can take much higher preheat temperatures.","flash":true,"source":"BEE Book 2 Ch 02 p78","order":2159},
{"id":"p2-b02-031","paper":2,"topic":"Incomplete Combustion","kind":"fact","front":"How large can unburnt carbon in coal firing be, as a share of heat supplied to the boiler?","back":"It can exceed 2% of the heat supplied, lost as grit carry-over or carbon in ash.","explain":"Non-uniform coal size is a common cause. In chain grate stokers, large lumps do not burn out and fines can block air passages.","flash":false,"source":"BEE Book 2 Ch 02 p78","order":2160},
{"id":"p2-b02-032","paper":2,"topic":"Excess Air","kind":"fact","front":"What typical excess air applies to a spreader stoker, a water-cooled pulverised coal furnace, and a natural gas high-pressure burner?","back":"Spreader stoker: 30–60%. Pulverised coal in a completely water-cooled furnace: 15–20%. Natural gas high-pressure burner: 5–7%.","explain":"Table 2.6 gives typical excess air levels. Some excess air is needed for complete combustion, but more than necessary carries heat up the stack.","flash":false,"source":"BEE Book 2 Ch 02 p79","order":2161},
{"id":"p2-b02-033","paper":2,"topic":"Excess Air","kind":"fact","front":"What efficiency gain follows from each 1% cut in excess air, and which methods reduce excess air?","back":"About 0.6% in efficiency. Portable O₂ analysers and draft gauges allow manual adjustment, with excess air reduction up to 20% feasible; a continuous O₂ analyser with a local readout adds a further 10–15%.","explain":"A remote-controlled damper positioner lets one operator control several firing systems from the control room. Automatic stack damper control is justified only for large systems.","flash":false,"source":"BEE Book 2 Ch 02 p80","order":2162},
{"id":"p2-b02-034","paper":2,"topic":"Boiler Loading","kind":"fact","front":"At what load does a boiler reach maximum efficiency, and what is the lowest load it should normally run at?","back":"Maximum efficiency is at about two-thirds of full load. Efficiency drops significantly below 25% of rated load, and operation below that should be avoided.","explain":"At zero output all the fuel only supplies losses, so efficiency is zero. Below half load most combustion appliances need more excess air, which raises the sensible heat loss.","flash":true,"source":"BEE Book 2 Ch 02 p81","order":2163},
{"id":"p2-b02-035","paper":2,"topic":"Boiler Scheduling","kind":"fact","front":"Is it more efficient to run many boilers at low load, or fewer boilers at higher loads?","back":"Fewer boilers at higher loads, because optimum efficiency occurs at about 65–85% of full load.","explain":"Running many boilers at low load pushes each one below its efficient band, which wastes fuel. Proper scheduling is a simple energy-saving measure.","flash":false,"source":"BEE Book 2 Ch 02 p81","order":2164},
{"id":"p2-b02-036","paper":2,"topic":"Boiler Efficiency (Direct Method)","kind":"problem","front":"A coal-fired boiler makes 8 TPH of dry saturated steam at 10 kg/cm²(g) with enthalpy 665 kcal/kg, from feed water at 85 °C (enthalpy 85 kcal/kg). It burns 1.8 TPH of coal with GCV 3,200 kcal/kg. Find the boiler efficiency by the direct method and the evaporation ratio.","back":"Efficiency about 80% on GCV basis (calculated 80.6%; the book rounds to 80%). Evaporation ratio = 4.44 kg steam per kg coal.","explain":"The direct method compares the energy gained by the water and steam with the energy in the fuel. Evaporation ratio is steam output divided by fuel input.","flash":false,"source":"BEE Book 2 Ch 02 p60","steps":[{"prompt":"Convert the steam and fuel flows to kg/h.","answer":"Steam Q = 8,000 kg/h; coal q = 1,800 kg/h.","explain":"Use the same units throughout; 1 TPH = 1,000 kg/h."},{"prompt":"Find the heat gained per kg of steam (hg − hf).","answer":"665 − 85 = 580 kcal/kg.","explain":"This is the enthalpy rise of the working fluid from feed water to steam."},{"prompt":"Find the heat output per hour.","answer":"8,000 × 580 = 4,640,000 kcal/h.","explain":"Heat output is steam flow multiplied by the enthalpy gain."},{"prompt":"Find the heat input per hour.","answer":"1,800 × 3,200 = 5,760,000 kcal/h.","explain":"Heat input is fuel flow multiplied by GCV."},{"prompt":"Compute the efficiency and the evaporation ratio.","answer":"Efficiency = 4,640,000 / 5,760,000 × 100 = 80.6% (book: 80%). Evaporation ratio = 8,000 / 1,800 = 4.44.","explain":"Efficiency is on a GCV basis because GCV was used; an NCV basis would give a higher figure."}],"order":2165},
{"id":"p2-b02-037","paper":2,"topic":"Boiler Efficiency (Indirect Method)","kind":"problem","front":"A 20 TPH boiler burns coal with GCV 4,291 kcal/kg and ultimate analysis C 53.65%, H₂ 3.25%, N₂ 1.11%, O₂ 8.68%, S 0.34%, moisture 14.43%, ash 18.54%. Flue gas: O₂ 9%, CO 800 ppm, CO₂ 10.67%, 180 °C. Ambient 29.3 °C, air humidity 0.01977 kg/kg dry air. Unburnts: 0.11% in bottom ash (GCV 889 kcal/kg) and 4.89% in fly ash (GCV 395 kcal/kg). Find the boiler efficiency by the indirect method.","back":"About 80.7% on GCV basis. Losses total 19.3%: dry flue gas 10.7%, H₂ 4.4%, moisture in fuel 2.2%, moisture in air 0.38%, partial C to CO 0.53%, radiation 1.0%, fly ash unburnts 0.084%, bottom ash unburnts 0.004%.","explain":"The indirect method subtracts each percentage loss from 100. Dry flue gas is the largest loss, so it drives most of the improvement work. The book prints L5 as 0.53%; recomputing its formula gives about 0.49%, which still gives 80.7% overall.","flash":false,"source":"BEE Book 2 Ch 02 p61","steps":[{"prompt":"Find the theoretical air (kg/kg coal) using [11.6C + 34.8(H₂ − O₂/8) + 4.35S] / 100.","answer":"(11.6 × 53.65 + 34.8 × (3.25 − 8.68/8) + 4.35 × 0.34) / 100 = 6.99, about 7.0 kg/kg coal.","explain":"The formula uses ultimate analysis percentages; the oxygen in the fuel offsets part of the hydrogen's air requirement."},{"prompt":"Find the % excess air from the measured flue gas O₂: EA = O₂ / (21 − O₂) × 100.","answer":"9 / (21 − 9) × 100 = 75%.","explain":"Excess air is the unused oxygen compared with the 21% O₂ in air."},{"prompt":"Find the actual air supplied: (1 + EA/100) × theoretical air.","answer":"1.75 × 7.0 = 12.3 kg/kg coal.","explain":"Actual air is the theoretical air plus the excess air."},{"prompt":"Find the mass of dry flue gas (kg/kg coal): CO₂ + N₂ from fuel + N₂ from air + excess O₂ + SO₂.","answer":"0.5365 × 44/12 = 1.97; N₂ fuel 0.0111; N₂ air 12.3 × 0.77 = 9.47; O₂ (12.3 − 7) × 0.23 = 1.22; SO₂ 0.0034 × 64/32 = 0.007. Total = 12.7 kg/kg coal.","explain":"Water vapour is excluded from dry flue gas; it is handled in the L2 and L4 losses."},{"prompt":"Find L1, the dry flue gas loss: m × Cp × (Tf − Ta) / GCV × 100.","answer":"12.7 × 0.24 × (180 − 29.3) / 4,291 × 100 = 10.7%.","explain":"Cp of flue gas is 0.24 kcal/kg °C. This is the largest loss in the example."},{"prompt":"Add all losses and subtract from 100.","answer":"L1 10.7 + L2 4.4 + L3 2.2 + L4 0.38 + L5 0.53 + L6 1.0 (assumed) + L7 0.084 + L8 0.004 = 19.3%. Efficiency = 100 − 19.3 = 80.7%.","explain":"L2 (hydrogen), L3 (fuel moisture), L4 (air moisture) and L5 (partial combustion) come from the book's formulas. L6 radiation is assumed at 1%."}],"order":2166},
{"id":"p2-b02-038","paper":2,"topic":"Boiler Blowdown","kind":"problem","front":"A package boiler has a maximum permissible TDS of 3,000 ppm, make-up water of 10% of feed water and feed water TDS of 300 ppm. Find the blowdown percentage, and the blowdown rate when evaporation is 3,000 kg/h.","back":"Blowdown about 1.11% of feed water; at 3,000 kg/h evaporation this is about 33.3 kg/h.","explain":"Blowdown is set so that boiler water TDS stays at or below the limit. Higher feed TDS or higher make-up raises the blowdown needed.","flash":false,"source":"BEE Book 2 Ch 02 p72","steps":[{"prompt":"Write the blowdown formula.","answer":"% blowdown = (feed TDS × % make-up × 100) / (maximum permissible TDS − feed TDS).","explain":"Feed TDS in the numerator sets how much solids enter; the denominator is the allowed concentration margin."},{"prompt":"Substitute the values.","answer":"300 × (10/100) × 100 / (3,000 − 300) = 3,000 / 2,700 = 1.11%.","explain":"Make-up is entered as a percentage of feed water."},{"prompt":"Find the blowdown rate at 3,000 kg/h evaporation.","answer":"3,000 × 1.11 / 100 = 33.3 kg/h.","explain":"The book takes the blowdown percentage on the evaporation rate in this example."}],"order":2167},
{"id":"p2-b02-039","paper":2,"topic":"Boiler Blowdown","kind":"problem","front":"An oil-fired boiler makes 30 t/h of steam and runs 8,000 h/yr. Feed water TDS is cut from 500 to 200 ppm. Maximum boiler TDS is 3,000 ppm and make-up is 10%. Blowdown water is at 170 °C, feed water at 40 °C, fuel GCV 10,000 kcal/kg and boiler efficiency 80%. Find the annual fuel oil saving.","back":"About 6.3 kg/h of fuel oil, or about 50 tonnes per year (book: 50.24 t/yr).","explain":"Lower feed water TDS cuts the blowdown rate, so less hot water is discarded and less heat and fuel are needed to replace it.","flash":false,"source":"BEE Book 2 Ch 02 p82","steps":[{"prompt":"Find the initial blowdown %: 500 × 10 / (3,000 − 500).","answer":"2.0%.","explain":"Use the blowdown formula from the chapter with feed TDS of 500 ppm."},{"prompt":"Find the improved blowdown %: 200 × 10 / (3,000 − 200).","answer":"0.71%.","explain":"Only the feed water TDS changes."},{"prompt":"Find the reduction in blowdown, in % and in kg/h.","answer":"2.0 − 0.71 = 1.29%; 1.29 × 30,000 / 100 = 387 kg/h.","explain":"The percentage is applied to the 30 t/h steam rate."},{"prompt":"Find the heat saved per hour.","answer":"387 × 1 × (170 − 40) = 50,310 kcal/h.","explain":"Heat saved is the blowdown flow times the specific heat times the temperature drop of the blowdown water to feed water temperature."},{"prompt":"Find the fuel oil saved per hour.","answer":"50,310 / (10,000 × 0.80) = 6.28 kg/h.","explain":"Divide the heat saved by the fuel GCV and the boiler efficiency."},{"prompt":"Find the annual saving.","answer":"6.28 × 8,000 = 50.24 t/yr, about 50 tonnes of fuel oil per year.","explain":"Multiply the hourly saving by the annual operating hours."}],"order":2168},
{"id":"p2-b02-040","paper":2,"topic":"Boiler Efficiency (Evaporation Ratio)","kind":"problem","front":"A coal-fired boiler has an evaporation ratio of 4. Steam enthalpy is 640 kcal/kg, feed water is at 55 °C and coal GCV is 4,000 kcal/kg. Estimate the boiler efficiency.","back":"About 58.5% on GCV basis.","explain":"Efficiency equals the evaporation ratio times the enthalpy gain per kg of steam, divided by the fuel GCV.","flash":false,"source":"BEE Book 2 Ch 02 p83","steps":[{"prompt":"Write efficiency in terms of evaporation ratio.","answer":"η = EvR × (steam enthalpy − feed water enthalpy) / GCV × 100.","explain":"Heat output is steam flow times enthalpy gain; heat input is fuel flow times GCV; their ratio is EvR times the enthalpy gain over GCV."},{"prompt":"Find the feed water enthalpy at 55 °C.","answer":"About 55 kcal/kg.","explain":"The worked example in the chapter takes feed water enthalpy equal to its temperature in kcal/kg (85 °C gives 85 kcal/kg)."},{"prompt":"Substitute the values.","answer":"4 × (640 − 55) / 4,000 = 4 × 585 / 4,000 = 0.585.","explain":"Enthalpy gain per kg steam is 585 kcal/kg."},{"prompt":"Express as a percentage.","answer":"η = 58.5% on GCV basis.","explain":"Multiply by 100."}],"order":2169},
{"id":"p2-b02-041","paper":2,"topic":"Boiler Blowdown","kind":"problem","front":"A drum has a permissible TDS of 2,000 ppm, make-up water is 10% of feed water and feed water TDS is 200 ppm. Find the blowdown percentage.","back":"About 1.11%.","explain":"This uses the same formula as the chapter's worked blowdown example. A lower permissible TDS raises the blowdown needed.","flash":false,"source":"BEE Book 2 Ch 02 p83","steps":[{"prompt":"Write the blowdown formula.","answer":"% blowdown = (feed TDS × % make-up × 100) / (maximum permissible TDS − feed TDS).","explain":"Use the boiler's permissible TDS, not the feed water TDS, in the denominator."},{"prompt":"Substitute the values.","answer":"200 × 10 / (2,000 − 200) = 2,000 / 1,800.","explain":"Make-up of 10% enters as 10."},{"prompt":"Find the blowdown percentage.","answer":"1.11%.","explain":"This matches the chapter's example with 3,000 ppm, which gives the same 1.11% at 300 ppm feed TDS."}],"order":2170}
]$cards$::jsonb);
